    let nw = textureSampleLevel(source, sourceSampler, in.uv + texel * vec2f(-1.0, -1.0), 0.0).rgb;
    let ne = textureSampleLevel(source, sourceSampler, in.uv + texel * vec2f(1.0, -1.0), 0.0).rgb;
